class Solution {
  private int rank;
  private String answer = "";

  public String getHappyString(int n, int k) {
    rank = k;
    build(new StringBuilder(), n);
    return answer;
  }

  private void build(StringBuilder current, int n) {
    if (!answer.isEmpty()) return;
    if (current.length() == n) {
      if (--rank == 0) answer = current.toString();
      return;
    }
    for (char c = 'a'; c <= 'c'; c++) {
      if (current.length() > 0 && current.charAt(current.length() - 1) == c) continue;
      current.append(c);
      build(current, n);
      current.deleteCharAt(current.length() - 1);
    }
  }
}
